import{_ as t,o as n,c as o,a2 as i}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Sign in to an agent provider","description":"","frontmatter":{},"headers":[],"relativePath":"provider-login.md","filePath":"provider-login.md","lastUpdated":1793867462000}'),s={name:"provider-login.md"};function a(r,e,d,l,c,h){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="sign-in-to-an-agent-provider" tabindex="-1">Sign in to an agent provider <a class="header-anchor" href="#sign-in-to-an-agent-provider" aria-label="Permalink to &quot;Sign in to an agent provider&quot;">​</a></h1><p>Sessions with <strong>Subscription</strong> billing use your own login at the agent&#39;s provider. You sign in once, inside a session; AgentHub stores the resulting login for your account and restores it into later sessions. Signing in to the AgentHub web app is a separate login.</p><p><strong>Edition:</strong> Community · <strong>Who:</strong> every user, for their own provider logins.</p><h2 id="sign-in-from-the-workspace" tabindex="-1">Sign in from the Workspace <a class="header-anchor" href="#sign-in-from-the-workspace" aria-label="Permalink to &quot;Sign in from the Workspace&quot;">​</a></h2><p>For <strong>Claude Code</strong> and <strong>Codex</strong>, the sign-in happens in the Workspace of an Interactive session:</p><ol><li>Create an Interactive session with the agent and <strong>Subscription</strong> billing.</li><li>When the CLI needs a login, a sign-in card appears in the conversation: <em>The agent CLI is waiting for its owner to sign in.</em> For Claude Code, type <code>/login</code> if the card does not appear by itself.</li><li>Open the link on the card and complete the sign-in in your browser. For a device code, the card shows the one-time code to enter there; when the provider shows you a code instead, paste it into the card.</li><li>The CLI continues by itself. <strong>Settings → Credentials</strong> now lists the stored account.</li></ol><p>The card has one main action per step; <strong>Open terminal</strong>, cancel and copy are secondary. Values shown during sign-in are kept out of the saved session state, and saving resumes once sign-in has completed.</p><h3 id="automatic-sign-in-for-claude-sessions" tabindex="-1">Automatic sign-in for Claude sessions <a class="header-anchor" href="#automatic-sign-in-for-claude-sessions" aria-label="Permalink to &quot;Automatic sign-in for Claude sessions&quot;">​</a></h3><p>A Claude session with no subscription login, no API key and no own model endpoint shows the sign-in card at start, without typing <code>/login</code>. An expired or invalid stored login is not detected this way: such a session starts as usual, and the CLI asks you to sign in again.</p><h2 id="sign-in-from-the-terminal" tabindex="-1">Sign in from the terminal <a class="header-anchor" href="#sign-in-from-the-terminal" aria-label="Permalink to &quot;Sign in from the terminal&quot;">​</a></h2><p>Cursor, OpenClaw and OpenCode sign in in the session&#39;s terminal. Open the Terminal interface, or <strong>⌘ Agent terminal</strong> in the Workspace, and run:</p><table tabindex="0"><thead><tr><th>Agent</th><th>Login in the session terminal</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>/login</code> inside Claude Code</td></tr><tr><td>Codex</td><td><code>codex login --device-auth</code></td></tr><tr><td>Cursor</td><td><code>agent login</code></td></tr><tr><td>OpenClaw</td><td><code>openclaw models auth add</code></td></tr><tr><td>OpenCode</td><td><code>opencode auth login</code>; choose the provider and complete its sign-in or enter its key</td></tr></tbody></table><p>For OpenCode Go, get the key from the OpenCode console and use it in the session&#39;s login flow. OpenCode Go and Zen use a key even when your billing is a subscription.</p><p>For <strong>API-key</strong> billing, store the key in <strong>Settings → Credentials</strong> and choose API-key mode when creating the session. A personal AgentHub <code>oah_</code> token is for the hub API, not an agent provider key.</p><p>Do not copy a workstation&#39;s credential files into the pod or paste login tokens into an agent chat.</p><h2 id="several-accounts-per-provider" tabindex="-1">Several accounts per provider <a class="header-anchor" href="#several-accounts-per-provider" aria-label="Permalink to &quot;Several accounts per provider&quot;">​</a></h2><p><strong>Settings → Credentials → Provider logins</strong> lists your stored logins per agent. For each one you can <strong>rename</strong> it, <strong>make default</strong> for new sessions, or remove it. When you have more than one login for an agent, the <strong>New session</strong> dialog offers an <strong>Account</strong> choice.</p><h2 id="usage-limits-and-account-failover" tabindex="-1">Usage limits and account failover <a class="header-anchor" href="#usage-limits-and-account-failover" aria-label="Permalink to &quot;Usage limits and account failover&quot;">​</a></h2><p>When a stored login reaches its provider&#39;s usage limit, AgentHub marks the account as at its limit until the window resets. The mark shows in <strong>Settings → Credentials</strong>, and <strong>clear limit</strong> removes it by hand.</p><ul><li>A running session that hits the limit is moved to another available login of the same provider, and you are notified. Turn this off per session with <strong>Edit session → Switch account automatically at usage limit</strong>; the account is then still marked, so new sessions avoid it.</li><li>New sessions avoid an account at its limit, unless you picked that account yourself.</li><li>Agents can check and switch accounts themselves with the <code>account_status</code> and <code>account_switch</code> tools (see Built-in tools inside a session).</li></ul><p>How AgentHub notices the limit differs per agent: Claude Code reports its rate-limit windows; for Codex, OpenClaw and OpenCode the CLI&#39;s own usage-limit notice is recognised. For Cursor, detection uses conservative output patterns that are not verified against the CLI.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Sign-in was tested with the pinned CLIs and test identities, not with real provider accounts. See <a href="/docs/troubleshooting#provider-login">Troubleshooting</a> if login is unavailable, and <a href="/docs/mcp">MCP clients</a> for signing an external client into AgentHub.</p>',23)])])}const p=t(s,[["render",a]]);export{u as __pageData,p as default};
